pub fn sign_of(x: i32) -> i32 {
    if x > 0 {
        1
    } else if x < 0 {
        -1
    } else {
        0
    }
}

pub fn sign(a: Vec<i32>) -> Vec<i32> {
    // Preserve order; output length equals input length.
    a.into_iter().map(sign_of).collect()
}

